using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Reflection.Metadata;
using System.Reflection.PortableExecutable;

var path = "/home/runner/.nuget/packages/xunit.v3.extensibility.core/1.1.0/lib/netstandard2.0/xunit.v3.core.dll";
using var fs = File.OpenRead(path);
using var pe = new PEReader(fs);
var mr = pe.GetMetadataReader();
foreach (var tdh in mr.TypeDefinitions) {
    var td = mr.GetTypeDefinition(tdh);
    var name = mr.GetString(td.Name);
    if (name == "ITestCaseOrderer") {
        Console.WriteLine($"Found: {mr.GetString(td.Namespace)}.{name}");
        foreach (var mh in td.GetMethods()) {
            var md = mr.GetMethodDefinition(mh);
            Console.WriteLine($"  Method: {mr.GetString(md.Name)}");
            var sig = md.DecodeSignature(new DisassemblingSignatureTypeProvider(), null);
            Console.WriteLine($"    Return: {sig.ReturnType}");
            foreach (var p in sig.ParameterTypes) Console.WriteLine($"    Param: {p}");
            // Check generic params
            foreach (var gph in md.GetGenericParameters()) {
                var gp = mr.GetGenericParameter(gph);
                Console.WriteLine($"    GenericParam: {mr.GetString(gp.Name)} attrs={gp.Attributes}");
                foreach (var gc in gp.GetConstraints()) {
                    var constraint = mr.GetGenericParameterConstraint(gc);
                    Console.WriteLine($"      Constraint: {constraint.Type.Kind}");
                }
            }
        }
    }
}

class DisassemblingSignatureTypeProvider : ISignatureTypeProvider<string, object?> {
    public string GetPrimitiveType(PrimitiveTypeCode typeCode) => typeCode.ToString();
    public string GetTypeFromDefinition(MetadataReader reader, TypeDefinitionHandle handle, byte rawTypeKind) {
        var td = reader.GetTypeDefinition(handle);
        return $"{reader.GetString(td.Namespace)}.{reader.GetString(td.Name)}";
    }
    public string GetTypeFromReference(MetadataReader reader, TypeReferenceHandle handle, byte rawTypeKind) {
        var tr = reader.GetTypeReference(handle);
        return $"{reader.GetString(tr.Namespace)}.{reader.GetString(tr.Name)}";
    }
    public string GetSZArrayType(string elementType) => $"{elementType}[]";
    public string GetGenericInstantiation(string genericType, System.Collections.Immutable.ImmutableArray<string> typeArguments) => $"{genericType}<{string.Join(",", typeArguments)}>";
    public string GetArrayType(string elementType, ArrayShape shape) => $"{elementType}[{new string(',', shape.Rank - 1)}]";
    public string GetByReferenceType(string elementType) => $"ref {elementType}";
    public string GetPointerType(string elementType) => $"{elementType}*";
    public string GetFunctionPointerType(MethodSignature<string> signature) => "fnptr";
    public string GetGenericMethodParameter(object? genericContext, int index) => $"!!{index}";
    public string GetGenericTypeParameter(object? genericContext, int index) => $"!{index}";
    public string GetModifiedType(string modifier, string unmodifiedType, bool isRequired) => unmodifiedType;
    public string GetPinnedType(string elementType) => elementType;
    public string GetTypeFromSpecification(MetadataReader reader, object? genericContext, TypeSpecificationHandle handle, byte rawTypeKind) => "typespec";
}
